import React from 'react';
import { motion } from 'framer-motion';
import { useTranslation } from 'react-i18next';
import { FiChevronLeft, FiChevronRight, FiZap, FiClock } from 'react-icons/fi';
import { isToday, addMonths, format } from 'date-fns';

const DAY_KEYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];

const getLocalizedMonth = (date, language) => {
  return new Intl.DateTimeFormat(language === 'ar' ? 'ar-EG' : language === 'fr' ? 'fr-FR' : 'en-US', {
    month: 'long',
    year: 'numeric',
    numberingSystem: 'latn',
  }).format(date);
};

const CalendarGrid = ({
  currentDate, setCurrentDate,
  calendarDays, handleDayClick,
  itemVariants
}) => {
  const { t, i18n } = useTranslation('agendamanagement');
  const isRtl = i18n.language === 'ar';
  const lang = i18n.language;

  const dayLabels = DAY_KEYS.map(k => t(`calendar.daysShort.${k}`));
  const monthYearLabel = getLocalizedMonth(currentDate, lang);

  return (
    <>
      {/* Month Navigation */}
      <motion.div variants={itemVariants} className="mb-6" dir={isRtl ? 'rtl' : 'ltr'}>
        <div className="bg-gray-900/50 backdrop-blur-sm rounded-2xl border border-gray-700/50 p-6">
          <div className={`flex flex-wrap justify-between items-center gap-3 ${isRtl ? 'flex-row-reverse' : ''}`}>
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={() => setCurrentDate(addMonths(currentDate, isRtl ? 1 : -1))}
              className="p-2 rounded-xl bg-gray-800/50 text-gray-300 hover:text-white border border-gray-700/50"
            >
              {isRtl ? <FiChevronRight className="w-5 h-5" /> : <FiChevronLeft className="w-5 h-5" />}
            </motion.button>

            <div className="flex flex-col items-center">
              <h2 className="text-xl font-bold text-white capitalize">{monthYearLabel}</h2>
              <button
                onClick={() => setCurrentDate(new Date())}
                className="text-sm text-[#00d0cb] hover:text-[#4fb0ff] mt-1 flex items-center gap-1"
              >
                <FiZap className="text-xs" />
                {t('actions.today')}
              </button>
            </div>

            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={() => setCurrentDate(addMonths(currentDate, isRtl ? -1 : 1))}
              className="p-2 rounded-xl bg-gray-800/50 text-gray-300 hover:text-white border border-gray-700/50"
            >
              {isRtl ? <FiChevronLeft className="w-5 h-5" /> : <FiChevronRight className="w-5 h-5" />}
            </motion.button>
          </div>
        </div>
      </motion.div>

      {/* Calendar Grid */}
      <motion.div
        variants={itemVariants}
        className="overflow-x-auto custom-scrollbar pb-2"
        dir={isRtl ? 'rtl' : 'ltr'}
      >
        <div className="grid grid-cols-7 gap-2 mb-4 min-w-[700px] md:min-w-0">
          {/* Day Headers */}
          {dayLabels.map((day, idx) => (
            <div key={idx} className="text-center font-medium text-gray-300 py-3 text-sm">
              {day}
            </div>
          ))}

          {/* Calendar Days */}
          {calendarDays.map((day, index) => (
            <motion.div
              key={index}
              whileHover={{ scale: 1.02 }}
              className={`min-h-[112px] p-2 rounded-xl cursor-pointer transition-all border ${
                day.isCurrentMonth
                  ? 'bg-gray-900/30 border-gray-700/50'
                  : 'bg-gray-900/10 border-gray-700/30 text-gray-500'
              } ${isToday(day.date) ? 'border-[#00d0cb] ring-2 ring-[#00d0cb]/20' : ''}`}
              onClick={() => handleDayClick(day.date)}
            >
              <div className={`text-sm font-medium p-1 ${isRtl ? 'text-left' : 'text-right'} ${isToday(day.date) ? 'text-[#00d0cb] font-bold' : 'text-gray-300'}`}>
                {format(day.date, 'd')}
              </div>

              <div className="space-y-1 max-h-24 overflow-y-auto pr-1">
                {day.events.slice(0, 4).map(event => (
                  <motion.div
                    key={event.id}
                    initial={{ opacity: 0, y: 5 }}
                    animate={{ opacity: 1, y: 0 }}
                    className={`p-1.5 rounded-lg truncate border ${
                      event._isTraining
                        ? 'bg-gradient-to-r from-emerald-500/20 to-teal-500/20 border-emerald-500/30'
                        : event.type === 'Tournament'
                          ? 'bg-gradient-to-r from-[#902bd1]/20 to-[#00d0cb]/20 border-[#902bd1]/30'
                          : 'bg-gradient-to-r from-[#4fb0ff]/20 to-[#00d0cb]/20 border-[#00d0cb]/30'
                    }`}
                  >
                    <div className={`flex items-center gap-1 mb-0.5 ${isRtl ? 'flex-row-reverse' : ''}`}>
                      {event._isTraining && (
                        <span className="text-[0.55rem] font-bold px-1 py-0 rounded bg-emerald-500/30 text-emerald-300 shrink-0 leading-tight">
                          {t('badges.coachLabel')}
                        </span>
                      )}
                      <div className="font-medium text-xs truncate text-white">{event.title}</div>
                    </div>
                    <div className={`text-[0.65rem] text-gray-400 flex items-center gap-1 ${isRtl ? 'flex-row-reverse' : ''}`}>
                      <FiClock size={10} />
                      {format(new Date(event.date), 'HH:mm')}
                    </div>
                  </motion.div>
                ))}
                {day.events.length > 4 && (
                  <div className={`text-xs text-gray-500 italic ${isRtl ? 'pr-1 text-right' : 'pl-1'}`}>
                    {t('calendar.moreEvents', { count: day.events.length - 4 })}
                  </div>
                )}
              </div>
            </motion.div>
          ))}
        </div>
      </motion.div>
    </>
  );
};

export default CalendarGrid;
